+import assert from "node:assert/strict";
+import { test } from "node:test";
+
+import { JSDOM } from "jsdom";
+import { act, createElement } from "react";
+import { createRoot } from "react-dom/client";
+
+import {
+  FacilityOrganizationRead,
+  FacilityOrganizationType,
+} from "@/types/facilityOrganization/facilityOrganization";
+
+import { useOrganizationSelection } from "./useOrganizationSelection";
+
+function organization(id: string, name = id): FacilityOrganizationRead {
+  return {
+    id,
+    name,
+    description: "",
+    org_type: FacilityOrganizationType.DEPT,
+    active: true,
+    level_cache: 0,
+    has_children: false,
+    created_at: "2026-01-01T00:00:00Z",
+    updated_at: "2026-01-01T00:00:00Z",
+    permissions: [],
+  };
+}
+
+test("organization selection follows controlled IDs without effects and preserves unresolved IDs", async () => {
+  const dom = new JSDOM("<!doctype html><div id='root'></div>");
+  const globals = {
+    window: dom.window,
+    document: dom.window.document,
+    IS_REACT_ACT_ENVIRONMENT: true,
+  };
+  const previousGlobals = new Map(
+    Object.keys(globals).map((key) => [
+      key,
+      Object.getOwnPropertyDescriptor(globalThis, key),
+    ]),
+  );
+  for (const [key, value] of Object.entries(globals)) {
+    Object.defineProperty(globalThis, key, { value, configurable: true });
+  }
+  const changes: { ids: string[] | null; records: FacilityOrganizationRead[] }[] = [];
+  let selection: ReturnType<typeof useOrganizationSelection>;
+  let renders = 0;
+  function Harness(props: {
+    value?: string[] | null;
+    currentOrganizations?: FacilityOrganizationRead[];
+    singleSelection?: boolean;
+  }) {
+    renders++;
+    selection = useOrganizationSelection({
+      ...props,
+      singleSelection: props.singleSelection ?? false,
+      onChange: (ids, records) => changes.push({ ids, records: records ?? [] }),
+    });
+    return null;
+  }
+
+  const root = createRoot(dom.window.document.getElementById("root")!);
+  const first = organization("first");
+  const second = organization("second");
+  try {
+    await act(async () => root.render(createElement(Harness, { value: [first.id] })));
+    assert.deepEqual(selection!.selectedIds, [first.id]);
+    assert.deepEqual(selection!.selectedOrganizations, []);
+    await act(async () => selection.selectOrganization(second));
+    assert.deepEqual(changes.at(-1)?.ids, [first.id, second.id]);
+    // An ID whose label has not arrived must not disappear from the next edit.
+    assert.deepEqual(selection!.selectedIds, [first.id]);
+
+    const beforeProps = renders;
+    await act(async () => root.render(createElement(Harness, {
+      value: [first.id, second.id],
+      currentOrganizations: [first],
+    })));
+    assert.equal(renders, beforeProps + 1, "prop changes need no synchronization render");
+    assert.deepEqual(selection!.selectedOrganizations, [first, second]);
+    assert.equal(changes.length, 1, "receiving props must not echo a change to the parent");
+
+    await act(async () => selection.selectOrganization({ ...second }));
+    assert.equal(changes.length, 1, "duplicate detection uses IDs rather than object identity");
+    await act(async () => selection.removeOrganization(second.id));
+    assert.deepEqual(changes.at(-1)?.ids, [first.id]);
+
+    const renamed = organization(first.id, "Updated department");
+    await act(async () => root.render(createElement(Harness, {
+      value: [first.id],
+      currentOrganizations: [renamed],
+    })));
+    assert.equal(selection!.selectedOrganizations[0].name, renamed.name);
+    await act(async () => root.render(createElement(Harness, { value: null })));
+    assert.deepEqual(selection!.selectedOrganizations, []);
+    assert.equal(changes.length, 2, "external resets must not emit another change");
+
+    // Callers such as CareTeamSheet deliberately omit value.
+    await act(async () => root.render(createElement(Harness, { key: "uncontrolled" })));
+    await act(async () => selection.selectOrganization(first));
+    await act(async () => selection.selectOrganization(second));
